const messages = paragraphs.map((p, i) => (voiced[i] ? [voiced[i]] : isGroup ? 拆成消息段(p) : [{ type: 'text', data: { text: p } }]));
// [FS-VOICE-NO-ECHO] 已转语音的段，文字不得再进文字出站列表：这一格只留 record，
// 别处追加进来的 text 段一律剔掉。同一句既发语音又发文字，看的人最出戏。
for (let i = 0; i < messages.length; i += 1) {
	if (!voiced[i]) continue;
	const before = messages[i].length;
	messages[i] = messages[i].filter((seg) => seg?.type === 'record');
	if (messages[i].length !== before) voiceTrace('gateway-noecho', { channelId: row.channel_id, i, dropped: before - messages[i].length });
}
